    "kidStory": "小朋友放學後最期待什麼？當然是跟好朋友一起去草地上奔跑玩耍啦！春天二月的時候，小草剛長出綠油油的嫩芽，黃鶯鳥在樹枝間唱著歌。村子裡的小朋友一聽到放學鐘聲，背起書包像小鳥一樣跑回家，拿出了親手做的大蝴蝶風箏、小金魚風箏，在春風裡一邊笑一邊拚命往前跑，看著風箏越飛越高，飛到藍天白雲裡！這幅畫面是不是跟你們現在一模一樣呀？",
