    "kidStory": "千古第一才女李清照姊姊小時候，也是個超級活潑可愛的大玩家呢！十六歲那個夏天，她跟好朋友們划著小船去荷花池玩，吃點心、捉迷藏，玩到太陽下山都不想回家。等天黑要划船回去時，找不到路啦！小船卡進了比人還高的大荷花叢裡。大家嘻嘻哈哈一邊大叫「快划！快划！」，水花四濺，把在沙洲上睡覺的大群水鳥嚇了一大跳，水鳥們撲騰撲騰拍著翅膀滿天飛！這個熱鬧好玩的夏天傍晚，讓李清照記了一輩子！",
