    "kidStory": "清明節這天，天上下著細細密密的春雨，像輕輕的霧氣一樣飄過來。一個在異鄉趕路的叔叔，衣服都被淋得有些濕冷，想到天上的親人，心裡酸酸的。這時候，他看到前面有一隻大水牛，牛背上坐著一個戴斗笠的小牧童，悠哉悠哉地吹著笛子。叔叔趕緊跑過去問：「小朋友，請問附近哪裡有可以休息避雨的小店呀？」小牧童手一指：「你看！就在前面那一叢開滿粉紅杏花的村子裡！」這首詩前半段濕冷，後半段因為小牧童那一指，立刻變得溫暖又有希望！",
