    "kidStory": "很多小朋友去公園玩，遇到下雨就覺得好失望：「討厭，下雨就不好玩了！」但是我們最樂觀、最會玩的蘇東坡叔叔在杭州當市長時，帶著朋友在西湖划船。一開始出大太陽，湖面亮晶晶像撒滿了碎鑽石；過一會兒突然下起濛濛細雨，群山像罩上了一層薄紗裙。東坡叔叔拍手大笑說：「西湖就像大美女西施！出太陽是濃妝，下雨天是淡妝，晴天雨天都美極了！」因為這首詩，西湖從此多了一個美麗的名字——「西子湖」！",
