    "rhythmNotes": "全曲押霞、鴉、下、花等韻，朗朗上口，色彩明麗節奏輕快。",
    "recitationTips": "記住色彩口訣：暮景三象（村霞鴉） -> 飛雁動景 -> 五彩秋景（青綠白紅黃）。"
