    "appreciation": "這首詩是王維山水田園詩的代表作。全詩以「空靈靜謐」開篇，繼而以動襯靜，松間明月、石上清泉、竹喧浣女、蓮動漁舟，聲色動靜相生，展現出無比高潔純淨的心靈境界。",
    "background": "王維晚年隱居於終南山下的輞川別業。經歷了開元盛世與安史之亂的風雲變幻，他參禪悟道，在山水之間尋得身心的澄澈超脫。",
