    "appreciation": "《蜀道難》是中國古代浪漫主義詩歌的巔峯之一。李白以豐富奔放的奇思幻想，將蜀地的歷史傳說、神話、奇峯絕壑、激流奔雷熔於一爐，連用三次「蜀道之難，難於上青天」，層層遞進，震撼人心。",
