    "gradeLevel": "advanced",
    "gradeLabel": "初中拔尖經典",
    "illustrationEmoji": "🧗",
    "kidStory": "古代四川被重重疊疊的險峻高山包圍著，去四川的路叫「蜀道」，在懸崖峭壁上搭木頭棧道，旁邊就是萬丈深淵。李白發揮了他驚人的想像力：連飛得最高的黃鶴都飛不過去，猴子想爬都發愁！走在山頂上，伸手都能摸到天上的星星！李白寫這首詩提醒朋友們：人生旅途中也有很多像蜀道一樣險峻的難關，但只要勇敢面對、小心謹慎，就能跨越萬水千山！",
